-- Sesiunea 10 · baza de date „Aviatie” pentru Azure SQL Database
-- Generat de assets/s10/generate_s10.py. Rulați tot fișierul o singură dată, în baza goală
-- (SSMS sau Azure Data Studio; Query Editor din portal poate fi lent pe un fișier de aceste dimensiuni).
-- Scriptul se poate rula din nou: șterge întâi tabelele existente.
SET NOCOUNT ON;

DROP TABLE IF EXISTS dbo.Fact_Rezervari;
DROP TABLE IF EXISTS dbo.Fact_Zboruri;
DROP TABLE IF EXISTS dbo.Dim_Pasageri;
DROP TABLE IF EXISTS dbo.Dim_Canale;
DROP TABLE IF EXISTS dbo.Dim_Clase;
DROP TABLE IF EXISTS dbo.Dim_Aeronave;
DROP TABLE IF EXISTS dbo.Dim_Rute;
DROP TABLE IF EXISTS dbo.Dim_Companii;
DROP TABLE IF EXISTS dbo.Dim_Date;

CREATE TABLE dbo.Dim_Date (
    ID INT NOT NULL PRIMARY KEY,
    Data DATE NOT NULL,
    An SMALLINT,
    Trimestru CHAR(2),
    Luna TINYINT,
    Luna_Nume NVARCHAR(20),
    An_Luna CHAR(7),
    Zi_Saptamana NVARCHAR(10),
    Nr_Zi_Saptamana TINYINT,
    Weekend NVARCHAR(2),
    Sezon NVARCHAR(10)
);
CREATE TABLE dbo.Dim_Companii (
    ID INT NOT NULL PRIMARY KEY,
    Companie NVARCHAR(40),
    Cod_IATA CHAR(2),
    Tip_Companie NVARCHAR(20),
    Tara NVARCHAR(30),
    Alianta NVARCHAR(20),
    An_Infiintare SMALLINT
);
CREATE TABLE dbo.Dim_Rute (
    ID INT NOT NULL PRIMARY KEY,
    Cod_Ruta CHAR(7),
    Ruta NVARCHAR(60),
    Aeroport_Plecare CHAR(3),
    Oras_Plecare NVARCHAR(30),
    Tara_Plecare NVARCHAR(30),
    Aeroport_Sosire CHAR(3),
    Oras_Sosire NVARCHAR(30),
    Tara_Sosire NVARCHAR(40),
    Regiune_Sosire NVARCHAR(30),
    Distanta_km INT,
    Durata_Min INT,
    Tip_Ruta NVARCHAR(20),
    Latitudine_Sosire DECIMAL(9,4),
    Longitudine_Sosire DECIMAL(9,4)
);
CREATE TABLE dbo.Dim_Aeronave (
    ID INT NOT NULL PRIMARY KEY,
    Inmatriculare NVARCHAR(10),
    Model NVARCHAR(30),
    Producator NVARCHAR(20),
    Locuri INT,
    Tip_Aeronava NVARCHAR(20),
    Autonomie_km INT,
    An_Fabricatie SMALLINT
);
CREATE TABLE dbo.Dim_Clase (
    ID INT NOT NULL PRIMARY KEY,
    Clasa NVARCHAR(20),
    Cod_Clasa CHAR(1),
    Bagaj_Inclus_kg INT,
    Ordine TINYINT
);
CREATE TABLE dbo.Dim_Canale (
    ID INT NOT NULL PRIMARY KEY,
    Canal NVARCHAR(30),
    Tip_Canal NVARCHAR(10),
    Comision_Pct DECIMAL(5,2)
);
CREATE TABLE dbo.Dim_Pasageri (
    ID INT NOT NULL PRIMARY KEY,
    Cod_Pasager CHAR(6),
    Gen CHAR(1),
    Grupa_Varsta NVARCHAR(10),
    Tara NVARCHAR(30),
    Oras NVARCHAR(30),
    Nivel_Loialitate NVARCHAR(20),
    An_Inscriere SMALLINT
);
CREATE TABLE dbo.Fact_Zboruri (
    ID_Zbor INT NOT NULL PRIMARY KEY,
    Cod_Zbor NVARCHAR(8),
    ID_Date INT NOT NULL REFERENCES dbo.Dim_Date(ID),
    ID_Companie INT NOT NULL REFERENCES dbo.Dim_Companii(ID),
    ID_Ruta INT NOT NULL REFERENCES dbo.Dim_Rute(ID),
    ID_Aeronava INT NOT NULL REFERENCES dbo.Dim_Aeronave(ID),
    Ora_Plecare TIME(0),
    Status_Zbor NVARCHAR(12),
    Intarziere_Min INT,
    Locuri_Disponibile INT,
    Pasageri_Imbarcati INT,
    Venit_Bilete DECIMAL(12,2),
    Venit_Auxiliar DECIMAL(12,2),
    Cost_Combustibil DECIMAL(12,2),
    Cost_Operare DECIMAL(12,2)
);
CREATE TABLE dbo.Fact_Rezervari (
    ID_Rezervare INT NOT NULL PRIMARY KEY,
    Cod_Rezervare CHAR(9),
    ID_Date INT NOT NULL REFERENCES dbo.Dim_Date(ID),
    ID_Companie INT NOT NULL REFERENCES dbo.Dim_Companii(ID),
    ID_Ruta INT NOT NULL REFERENCES dbo.Dim_Rute(ID),
    ID_Clasa INT NOT NULL REFERENCES dbo.Dim_Clase(ID),
    ID_Canal INT NOT NULL REFERENCES dbo.Dim_Canale(ID),
    ID_Pasager INT NOT NULL REFERENCES dbo.Dim_Pasageri(ID),
    Zile_Avans INT,
    Nr_Bilete INT,
    Pret_Bilet DECIMAL(10,2),
    Taxe_Bilet DECIMAL(10,2),
    Bagaj_Extra DECIMAL(10,2),
    Valoare_Totala DECIMAL(12,2),
    Status_Rezervare NVARCHAR(12)
);










-- Verificare: numărul de rânduri din fiecare tabel
SELECT 'Dim_Date' AS Tabel, COUNT(*) AS Randuri FROM dbo.Dim_Date UNION ALL
SELECT 'Dim_Companii' AS Tabel, COUNT(*) AS Randuri FROM dbo.Dim_Companii UNION ALL
SELECT 'Dim_Rute' AS Tabel, COUNT(*) AS Randuri FROM dbo.Dim_Rute UNION ALL
SELECT 'Dim_Aeronave' AS Tabel, COUNT(*) AS Randuri FROM dbo.Dim_Aeronave UNION ALL
SELECT 'Dim_Clase' AS Tabel, COUNT(*) AS Randuri FROM dbo.Dim_Clase UNION ALL
SELECT 'Dim_Canale' AS Tabel, COUNT(*) AS Randuri FROM dbo.Dim_Canale UNION ALL
SELECT 'Dim_Pasageri' AS Tabel, COUNT(*) AS Randuri FROM dbo.Dim_Pasageri UNION ALL
SELECT 'Fact_Zboruri' AS Tabel, COUNT(*) AS Randuri FROM dbo.Fact_Zboruri UNION ALL
SELECT 'Fact_Rezervari' AS Tabel, COUNT(*) AS Randuri FROM dbo.Fact_Rezervari;

